import { describe, expect, it } from 'vitest'
import { kelvinToLinearRgb, lampLinearRgb } from './lamp'
import { whiteLevelsFor, whiteLevelsForKelvin, whiteMixColour, whiteMixKelvin, type Rgb } from './whiteMix'
import vector from '../../../src/test/resources/fixture/whiteMix.fixture.json'

// The shared vector, generated by an independent port of the model and pinned on the desk by
// WhiteMixTest: the warmth control and the desk must agree on every mix.
describe('whiteMix against the shared vector', () => {
  it('reads the black body and its adapted white as the desk does', () => {
    for (const entry of vector.blackBody) {
      kelvinToLinearRgb(entry.kelvin).forEach((v, i) => expect(v).toBeCloseTo(entry.rgb[i], 5))
      lampLinearRgb(entry.kelvin).forEach((v, i) => expect(v).toBeCloseTo(entry.adapted[i], 5))
    }
  })

  it('lands each colour on the same mix, and reads each mix back as the same colour and label', () => {
    for (const pair of vector.pairs) {
      for (const c of pair.levelsFor) {
        const levels = whiteLevelsFor(pair, c.colour as Rgb)
        expect([levels.warm, levels.cold], `${pair.warmKelvin}/${pair.coldKelvin} ${c.colour}`).toEqual(c.levels)
      }
      for (const c of pair.colourOf) {
        const [warm, cold] = c.levels
        expect(whiteMixColour(pair, warm, cold), `${c.levels}`).toEqual(c.colour)
        expect(whiteMixKelvin(pair, warm, cold)).toBe(c.kelvin)
      }
    }
  })
})

describe('whiteLevelsForKelvin', () => {
  const mix = { warmKelvin: 3000, coldKelvin: 6500 }

  it('is the label read backwards, the brighter white at the level', () => {
    for (const kelvin of [3000, 3500, 4300, 5200, 6500]) {
      const levels = whiteLevelsForKelvin(mix, kelvin, 200)
      expect(Math.max(levels.warm, levels.cold)).toBe(200)
      expect(Math.abs((whiteMixKelvin(mix, levels.warm, levels.cold) ?? 0) - kelvin)).toBeLessThanOrEqual(40)
    }
  })

  it('clamps to the pair and is off at level 0', () => {
    expect(whiteLevelsForKelvin(mix, 2000, 255)).toEqual({ warm: 255, cold: 0 })
    expect(whiteLevelsForKelvin(mix, 9000, 255)).toEqual({ warm: 0, cold: 255 })
    expect(whiteLevelsForKelvin(mix, 4000, 0)).toEqual({ warm: 0, cold: 0 })
  })
})
